create extension if not exists pgcrypto;
create table if not exists public.countries(id uuid primary key default gen_random_uuid(), name text not null, code text unique);
create table if not exists public.universities(id uuid primary key default gen_random_uuid(), country_id uuid references public.countries(id), name text not null, city text, website text, verified boolean default false);
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, university_id uuid references public.universities(id), program text, study_year int, avatar_url text, created_at timestamptz default now());
create table if not exists public.courses(id uuid primary key default gen_random_uuid(), university_id uuid references public.universities(id), code text, title text not null, description text);
create table if not exists public.enrollments(id uuid primary key default gen_random_uuid(), student_id uuid references public.profiles(id) on delete cascade, course_id uuid references public.courses(id) on delete cascade, progress numeric default 0, unique(student_id,course_id));
create table if not exists public.resources(id uuid primary key default gen_random_uuid(), university_id uuid references public.universities(id), course_id uuid references public.courses(id), title text not null, type text, file_url text, created_at timestamptz default now());
create table if not exists public.opportunities(id uuid primary key default gen_random_uuid(), title text not null, organization text, category text, country text, deadline date, url text, description text, created_at timestamptz default now());
create table if not exists public.listings(id uuid primary key default gen_random_uuid(), seller_id uuid references public.profiles(id) on delete cascade, title text not null, description text, price numeric, currency text default 'USD', category text, location text, created_at timestamptz default now());
create table if not exists public.communities(id uuid primary key default gen_random_uuid(), university_id uuid references public.universities(id), name text not null, description text);
create table if not exists public.posts(id uuid primary key default gen_random_uuid(), author_id uuid references public.profiles(id) on delete cascade, community_id uuid references public.communities(id), body text not null, created_at timestamptz default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(), sender_id uuid references public.profiles(id), recipient_id uuid references public.profiles(id), body text not null, created_at timestamptz default now());
alter table public.profiles enable row level security;
create policy "profiles own read" on public.profiles for select using (auth.uid() = id);
create policy "profiles own update" on public.profiles for update using (auth.uid() = id);
create policy "profiles own insert" on public.profiles for insert with check (auth.uid() = id);
alter table public.universities enable row level security;
create policy "universities public read" on public.universities for select using (true);
alter table public.opportunities enable row level security;
create policy "opportunities public read" on public.opportunities for select using (true);
